Given the head of a linked list, determine the starting node of the loop if a cycle exists. A loop occurs when the last node points back to an earlier node in the list. If no loop is present, return -1.Example: Input:  Output: 3Explanation: The linked list contains a loop, and the first node of the loop is 3.Input: Output: -1Explanation: No loop exists in the above linked list. So the output is -1.Try It YourselfTable of Content[Naive approach] Using Hashing - O(n) Time and O(n) Space[Expected Approach] Using Floyd's loop detection algorithm - O(n) Time and O(1) Space[Naive approach] Using Hashing - O(n) Time and O(n) SpaceThe idea is to start traversing the Linked List from head node and while traversing insert each node into the HashSet. If there is a loop present in the Linked List, there will be a node which will be already present in the hash set.If there is a node which is already present in the HashSet, return the node value which represent the starting node of loop.else, if there is no node which is already present in the HashSet , then return -1.
            C++

    #include <iostream>
#include <unordered_set>

using namespace std;

class Node {
public:
    int data;
    Node* next;
    Node(int x) {
        data = x;
        next = nullptr;
    }
};

int cycleStart(Node* head) {

    unordered_set<Node*> st; 

    Node* currNode = head; 

    // traverse the linked list
    while (currNode != nullptr) {

        // if the current node is already in the HashSet,
        // then this is the starting node of the loop
        if (st.find(currNode) != st.end()) {
            return currNode->data;  
        }

        st.insert(currNode);

        currNode = currNode->next;
    }

    return -1;
}

int main() {

    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);
    head->next->next->next->next = new Node(5);
    head->next->next->next->next->next = new Node(6);


    head->next->next->next->next->next = head->next->next;


    int loopNode = cycleStart(head);

    if (loopNode != -1)
        cout << loopNode;
    else
        cout << -1;

    return 0;
}


