        Node currNode = head;

        // Traverse the linked list
        while (currNode != null) {

            // If current node already in set → loop start
            if (set.contains(currNode)) {
                return currNode.data;
            }

            set.add(currNode);

            currNode = currNode.next;
        }

        return -1;
    }

